package com.gomgomapps.math.core;
import java.util.*;import java.util.regex.*;import org.junit.Test;import static org.junit.Assert.*;
public class PolyDivisionRelationsTest {
 private List<Rational> publicValues(Question q){String n="[+-]?\\d+(?:\\.\\d+)?(?:/\\d+)?";Matcher m=Pattern.compile("P\\(x\\)=x²("+n+")x("+n+")를 x-\\(("+n+")\\)로 나누면 몫은 x\\+b, 나머지는 ("+n+")입니다. b는\\?").matcher(q.prompt);assertTrue(q.prompt,m.matches());Rational linear=Expression.number(m.group(1)),constant=Expression.number(m.group(2)),a=Expression.number(m.group(3)),remainder=Expression.number(m.group(4)),b=linear.add(a);assertEquals("Independent constant-term identity",constant,remainder.sub(a.mul(b)));return List.of(linear,a,b);}
 @Test public void publicCoefficientIdentityControlsStepsAndSmallProblemsVary(){Generator g=new Generator(new Random(2090));Set<String> prompts=new HashSet<>(),answers=new HashSet<>();Set<Integer> positions=new HashSet<>();boolean negativeA=false,negativeLinear=false,zeroLinear=false,negativeResult=false,positiveResult=false;for(int i=0;i<1000;i++){Question q=g.next("sec_poly_division",List.of(),i%2==0);List<Rational> v=publicValues(q);Rational b=v.get(2);prompts.add(q.prompt);answers.add(b.toString());positions.add(q.correctChoice);negativeA|=v.get(1).compareTo(Rational.ZERO)<0;negativeLinear|=v.get(0).compareTo(Rational.ZERO)<0;zeroLinear|=v.get(0).equals(Rational.ZERO);negativeResult|=b.compareTo(Rational.ZERO)<0;positiveResult|=b.compareTo(Rational.ZERO)>0;assertTrue(v.get(1).compareTo(Rational.of(-7))>=0&&v.get(1).compareTo(Rational.of(7))<=0);assertTrue(b.compareTo(Rational.of(-7))>=0&&b.compareTo(Rational.of(7))<=0);assertTrue(new Checker().check(q,List.of(),List.of(b.toString())).correct());assertFalse(new Checker().check(q,List.of(),List.of(b.add(Rational.ONE).toString())).correct());verify(q,v);}assertTrue(prompts.size()>100);assertEquals(14,answers.size());assertTrue(positions.containsAll(Set.of(0,1,2,3)));assertTrue(negativeA&&negativeLinear&&zeroLinear&&negativeResult&&positiveResult);}
 private void verify(Question q,List<Rational> v){String signature=q.signature();StudyDiagram diagram=q.diagram;Arrays.fill(q.answers,"999999");q.choiceInputs=new Rational[]{Rational.of(999999)};HelpPlan p=HelpPlan.forQuestion(q);assertEquals(signature,q.signature());assertSame(diagram,q.diagram);assertFalse(p.canTransfer());assertEquals(3,p.size());List<String> frames=List.of("x항 계수 = ","나누는 식의 a = ","x항 계수 + a = ");for(int i=0;i<3;i++){assertEquals(frames.get(i),p.step(i).before);assertEquals("",p.step(i).after);assertTrue(p.step(i).accepts(v.get(i).toString()));assertTrue(p.step(i).accepts(v.get(i).decimalText()));assertFalse(p.step(i).accepts(v.get(i).add(Rational.ONE).toString()));}}
 @Test public void savedFractionsAndZeroAndOldAnswerLeakingDraftStayExact(){Question q=new Question("sec_poly_division","P(x)=x²+1/2x+23/6를 x-(-2/3)로 나누면 몫은 x+b, 나머지는 71/18입니다. b는?","","-1/6");verify(q,publicValues(q));Question zero=new Question("sec_poly_division","P(x)=x²+2x-5를 x-(-2)로 나누면 몫은 x+b, 나머지는 -5입니다. b는?","","0");verify(zero,publicValues(zero));HelpPlan p=HelpPlan.forQuestion(q);HelpPlan.Draft d=new HelpPlan.Draft();d.questionId=q.id;d.stage=1;d.entries=new ArrayList<>(List.of("-1/6"));p.restore(d,q.id);assertEquals(0,d.stage);assertEquals("",d.entries.get(0));assertEquals("poly-division-relations-v1",d.teachingVersion);d.entries.set(0,"1/2");d.stage=1;HelpPlan.Draft restored=HelpPlan.forQuestion(q).restore(d.copy(),q.id);assertEquals(1,restored.stage);assertEquals("1/2",restored.entries.get(0));}
}
